"use client"

import * as React from "react"
import { CircleCheck, Globe, IndianRupee, Loader2, Mail, MessageSquare, Phone, QrCode, ShieldAlert, TriangleAlert, Type, Wifi } from "lucide-react"

import { cn } from "@/lib/utils"
import { checkQr, DANGER_ISSUES, parseQr, QR_TRUSTED_DOMAINS, upiAmount, URL_SHORTENERS, type QrIssue, type QrPayload } from "./qr"

export { checkQr, DANGER_ISSUES, domainIn, isLookalike, parseQr, QR_TRUSTED_DOMAINS, registrableDomain, SHARED_HOST_SUFFIXES, upiAmount, URL_SHORTENERS, type QrIssue, type QrPayload } from "./qr"

/** Every visible string. Issue texts fill in `{printed}`, `{actual}`, `{twin}`, `{brand}`, `{shown}`, `{host}`, `{amount}` and `{recurText}`. */
export const QR_SCAN_MESSAGES = {
  heading: "Scanned code",
  types: { url: "Website", upi: "UPI payment", script: "Hidden script", tel: "Phone call", sms: "Text message", email: "Email", wifi: "Wi-Fi network", text: "Text", empty: "Empty" } as Record<QrPayload["type"], string>,
  mandate: "UPI AutoPay",
  goesTo: "Goes to",
  pays: "Pays",
  printed: "Printed or shown beside it",
  nameInCode: "Name in the code",
  nameNote: "Typed by whoever made the code. Your UPI app shows the bank's name before you enter your PIN.",
  amount: "Amount",
  note: "Note",
  verdict: { danger: "Don't open this yet", warning: "Check before you open", ok: "Goes where it says" },
  issues: {
    notPrinted: "The sign says {printed}, but this code goes to {actual}. Stickers over real codes do exactly this.",
    notPrintedLookalike: "The sign says {printed}, but this code goes to {actual}, a lookalike one letter off.",
    lookalike: "{actual} looks like {twin}, but it isn't.",
    brandInName: "{actual} uses {brand}'s name but isn't {brand}.",
    loginTrick: "The link starts with “{shown}@”, which hides the real site: {actual}.",
    script: "This code runs a script or opens a file instead of a web page.",
    apk: "Downloads an Android app. Install apps only from the Play Store.",
    shortener: "{host} is a link shortener, so the real destination is hidden.",
    punycode: "The address uses international characters ({host}) that can imitate familiar letters.",
    rawIp: "Goes to a bare IP address, not a named site.",
    http: "Not encrypted (http). Don't enter card details or passwords there.",
    upiReceive: "Scanning a UPI code only ever sends money. You never scan to receive a refund or prize.",
    upiNameMismatch: "The sign says {printed}, but the code pays {name}.",
    upiAmount: "{amount} is already filled in. Check it against the bill before you enter your PIN.",
    upiMandate: "This sets up AutoPay: repeated debits{recurText}, not a one-time payment. Only accept it for a subscription you chose.",
    smsBody: "Sends a text with a message already written. Read it before you send.",
  } as Record<Exclude<QrIssue["kind"], "notPrinted"> | "notPrinted" | "notPrintedLookalike", string>,
  resolving: "Following the short link…",
  resolvedTo: "Ends at {actual}",
  resolveFailed: "Couldn't follow the short link. Treat its destination as unknown.",
  empty: "Nothing readable in this code.",
  cancel: "Don't open",
  open: "Open {actual}",
  openAnyway: "Open anyway",
  pay: "Pay in UPI app",
  payAnyway: "Pay anyway",
  useAction: "Continue",
  goPrinted: "Go to {printed}",
}

export type QrScanMessages = typeof QR_SCAN_MESSAGES

const fill = (template: string, values: Record<string, unknown>) =>
  template.replace(/\{(\w+)\}/g, (match, key: string) => (values[key] === undefined ? match : String(values[key])))

const ICONS = { url: Globe, upi: IndianRupee, script: ShieldAlert, tel: Phone, sms: MessageSquare, email: Mail, wifi: Wifi, text: Type, empty: QrCode }
const button =
  "inline-flex h-9 items-center justify-center gap-2 rounded-md px-4 text-sm font-medium outline-none transition-colors focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:opacity-60"

export interface QrScanCheckProps extends Omit<React.ComponentProps<"div">, "children"> {
  /** The decoded text of the scanned code. */
  payload: string
  /** What is printed or shown beside the code: a domain ("paybyphone.com") or a merchant name. */
  printed?: string
  /** Brands to test for lookalikes. */
  trusted?: string[]
  /** Hosts treated as link shorteners. */
  shorteners?: string[]
  /** Follows a short link and resolves to its final URL (on your server; redirects can't be read from the browser). */
  resolveRedirect?: (url: string) => Promise<string>
  /** Called with what to open: the URL, the `upi://` link, or the tel/sms/mailto text. */
  onOpen?: (target: string) => void
  /** Called when the user decides not to open it. */
  onCancel?: () => void
  /** Locale for amounts. */
  locale?: string
  /** Any visible string; `types`, `verdict` and `issues` may be partial. */
  messages?: Partial<Omit<QrScanMessages, "types" | "verdict" | "issues">> & {
    types?: Partial<QrScanMessages["types"]>
    verdict?: Partial<QrScanMessages["verdict"]>
    issues?: Partial<QrScanMessages["issues"]>
  }
}

/**
 * Shows where a scanned QR code really goes before anything opens: the registrable domain in bold,
 * compared with what is printed beside the code (the sticker-over-the-real-code trick), lookalike
 * and brand-borrowing domains, hidden short links (followed through `resolveRedirect`), app
 * downloads, and for UPI codes the payee, a pre-filled amount and "scan to receive" refund scams.
 */
export function QrScanCheck({
  payload,
  printed = "",
  trusted = QR_TRUSTED_DOMAINS,
  shorteners = URL_SHORTENERS,
  resolveRedirect,
  onOpen,
  onCancel,
  locale = "en-IN",
  messages,
  className,
  ...props
}: QrScanCheckProps) {
  const t = {
    ...QR_SCAN_MESSAGES,
    ...messages,
    types: { ...QR_SCAN_MESSAGES.types, ...messages?.types },
    verdict: { ...QR_SCAN_MESSAGES.verdict, ...messages?.verdict },
    issues: { ...QR_SCAN_MESSAGES.issues, ...messages?.issues },
  }
  const scanned = React.useMemo(() => parseQr(payload), [payload])
  const [final, setFinal] = React.useState<{ from: string; payload?: QrPayload; failed?: boolean }>()
  const headingId = React.useId()
  const isShort = scanned.type === "url" && (shorteners.includes(scanned.registrable) || shorteners.includes(scanned.url.hostname))

  React.useEffect(() => {
    if (!isShort || !resolveRedirect || scanned.type !== "url") return
    let live = true
    const from = scanned.url.href
    Promise.resolve()
      .then(() => resolveRedirect(from))
      .then((to) => live && setFinal({ from, payload: parseQr(to) }))
      .catch(() => live && setFinal({ from, failed: true }))
    return () => {
      live = false
    }
  }, [isShort, resolveRedirect, scanned])

  const resolved = final && scanned.type === "url" && final.from === scanned.url.href ? final : undefined
  const shown = resolved?.payload && resolved.payload.type !== "empty" ? resolved.payload : scanned
  const issues = checkQr(shown, printed, trusted, shorteners).filter((issue) => !(resolved?.payload && issue.kind === "shortener"))
  if (resolved?.failed && !issues.some((i) => i.kind === "shortener")) issues.push({ kind: "shortener", host: scanned.type === "url" ? scanned.url.hostname : "" })
  const danger = issues.some((issue) => DANGER_ISSUES.includes(issue.kind))
  const state = scanned.type === "empty" ? "warning" : danger ? "danger" : issues.length ? "warning" : "ok"
  const pending = isShort && !!resolveRedirect && !resolved
  const Icon = ICONS[shown.type]
  const printedDomain = issues.find((issue): issue is Extract<QrIssue, { kind: "notPrinted" }> => issue.kind === "notPrinted")?.printed

  const describe = (issue: QrIssue) =>
    fill(issue.kind === "notPrinted" && issue.lookalike ? t.issues.notPrintedLookalike : t.issues[issue.kind], {
      ...issue,
      recurText: issue.kind === "upiMandate" && issue.recur ? ` (${issue.recur.toLowerCase()})` : "",
    })

  const target = shown.type === "url" ? shown.url.href : shown.raw
  const openLabel =
    shown.type === "upi" ? (danger ? t.payAnyway : t.pay) : danger ? t.openAnyway : shown.type === "url" ? fill(t.open, { actual: shown.registrable }) : t.useAction

  const row = (label: string, children: React.ReactNode) => (
    <div className="grid gap-0.5">
      <dt className="text-xs text-muted-foreground">{label}</dt>
      <dd className="min-w-0 break-words">{children}</dd>
    </div>
  )

  return (
    <div
      role="group"
      aria-labelledby={headingId}
      data-slot="qr-scan-check"
      data-state={state}
      className={cn(
        "w-full max-w-md space-y-3 rounded-lg border bg-card p-4 text-sm text-card-foreground shadow-xs",
        state === "danger" && "border-red-500/40",
        state === "warning" && "border-amber-500/40",
        className,
      )}
      {...props}
    >
      <div className="flex items-center justify-between gap-3">
        <h3 id={headingId} className="flex items-center gap-2 font-medium">
          <QrCode aria-hidden className="size-4 text-muted-foreground" />
          {t.heading}
        </h3>
        <span className="flex items-center gap-1.5 text-xs text-muted-foreground">
          <Icon aria-hidden className="size-3.5" />
          {shown.type === "upi" && shown.mandate ? t.mandate : t.types[shown.type]}
        </span>
      </div>

      {shown.type === "empty" ? (
        <p className="text-muted-foreground">{t.empty}</p>
      ) : (
        <dl className="grid gap-2">
          {shown.type === "url" &&
            row(
              t.goesTo,
              <span className="font-mono text-[13px] break-all">
                <span className="text-muted-foreground">{shown.url.hostname.slice(0, Math.max(0, shown.url.hostname.length - shown.registrable.length))}</span>
                <span className="text-base font-semibold text-foreground">{shown.registrable}</span>
                <span className="text-muted-foreground">{(shown.url.pathname === "/" ? "" : shown.url.pathname) + shown.url.search}</span>
              </span>,
            )}
          {shown.type === "upi" && (
            <>
              {row(t.pays, <span className="font-mono text-base font-semibold break-all">{shown.payee || "—"}</span>)}
              {shown.name && row(t.nameInCode, <span>{shown.name} <span className="block text-xs break-normal text-muted-foreground">{t.nameNote}</span></span>)}
              {upiAmount(shown.amount, shown.currency || "INR", locale) && row(t.amount, <span className="font-semibold">{upiAmount(shown.amount, shown.currency || "INR", locale)}</span>)}
              {shown.note && row(t.note, shown.note)}
            </>
          )}
          {(shown.type === "tel" || shown.type === "sms" || shown.type === "email" || shown.type === "wifi" || shown.type === "text") &&
            row(t.types[shown.type], <span className="font-mono">{shown.value}{shown.type === "sms" && shown.body && <span className="block font-sans text-muted-foreground">“{shown.body}”</span>}</span>)}
          {shown.type === "script" && row(t.types.script, <span className="font-mono text-xs">{shown.raw.slice(0, 80)}</span>)}
          {printed.trim() && row(t.printed, <span>{printed}</span>)}
        </dl>
      )}

      {pending && (
        <p className="flex items-center gap-1.5 text-xs text-muted-foreground">
          <Loader2 aria-hidden className="size-3.5 animate-spin" />
          {t.resolving}
        </p>
      )}
      {resolved?.payload?.type === "url" && <p className="text-xs text-muted-foreground">{fill(t.resolvedTo, { actual: resolved.payload.registrable })}</p>}
      {resolved?.failed && <p className="text-xs text-muted-foreground">{t.resolveFailed}</p>}

      <div aria-live="polite" className="space-y-1.5">
        {!pending && (
          <p className={cn("flex items-center gap-1.5 font-medium", state === "danger" ? "text-red-700 dark:text-red-400" : state === "warning" ? "text-amber-700 dark:text-amber-400" : "text-emerald-700 dark:text-emerald-400")}>
            {state === "danger" ? <ShieldAlert aria-hidden className="size-4 shrink-0" /> : state === "warning" ? <TriangleAlert aria-hidden className="size-4 shrink-0" /> : <CircleCheck aria-hidden className="size-4 shrink-0" />}
            {t.verdict[state]}
          </p>
        )}
        {issues.length > 0 && (
          <ul className="space-y-1 text-xs">
            {issues.map((issue) => (
              <li key={issue.kind} className={cn("flex gap-1.5 break-words", DANGER_ISSUES.includes(issue.kind) ? "text-red-700 dark:text-red-400" : "text-amber-700 dark:text-amber-400")}>
                <span aria-hidden className="mt-1.5 size-1 shrink-0 rounded-full bg-current" />
                <span className="min-w-0">{describe(issue)}</span>
              </li>
            ))}
          </ul>
        )}
      </div>

      {printedDomain && onOpen && (
        <button type="button" onClick={() => onOpen(`https://${printedDomain}`)} className={cn(button, "w-full border border-amber-500/40 text-amber-900 hover:bg-amber-500/10 dark:text-amber-200")}>
          <span className="truncate">{fill(t.goPrinted, { printed: printedDomain })}</span>
        </button>
      )}
      {(onOpen || onCancel) && shown.type !== "empty" && (
        <div className="flex flex-wrap justify-end gap-2">
          {onCancel && (
            <button type="button" onClick={onCancel} className={cn(button, danger ? "bg-primary text-primary-foreground hover:bg-primary/90" : "border hover:bg-accent")}>
              {t.cancel}
            </button>
          )}
          {onOpen && (
            <button
              type="button"
              disabled={pending}
              onClick={() => onOpen(target)}
              className={cn(button, "max-w-full min-w-0", danger ? "border border-red-500/40 text-red-700 hover:bg-red-500/10 dark:text-red-400" : "bg-primary text-primary-foreground hover:bg-primary/90")}
            >
              <span className="truncate">{openLabel}</span>
            </button>
          )}
        </div>
      )}
    </div>
  )
}

/** What a scanned QR code contains. */
export type QrPayload =
  | { type: "url"; raw: string; url: URL; registrable: string }
  | { type: "upi"; raw: string; payee: string; name?: string; amount?: string; note?: string; currency?: string; mandate?: boolean; recur?: string }
  | { type: "script"; raw: string }
  | { type: "tel" | "sms" | "email" | "wifi" | "text"; raw: string; value: string; body?: string }
  | { type: "empty"; raw: string }

/** One reason to pause before opening. `danger` ones are classic quishing tells. */
export type QrIssue =
  | { kind: "notPrinted"; printed: string; actual: string; lookalike: boolean }
  | { kind: "lookalike"; twin: string; actual: string }
  | { kind: "brandInName"; brand: string; actual: string }
  | { kind: "loginTrick"; shown: string; actual: string }
  | { kind: "script" }
  | { kind: "apk" }
  | { kind: "shortener"; host: string }
  | { kind: "punycode"; host: string }
  | { kind: "rawIp" }
  | { kind: "http" }
  | { kind: "upiReceive" }
  | { kind: "upiNameMismatch"; printed: string; name: string }
  | { kind: "upiAmount"; amount: string; currency: string }
  | { kind: "upiMandate"; recur?: string }
  | { kind: "smsBody" }

export const DANGER_ISSUES: QrIssue["kind"][] = ["notPrinted", "lookalike", "brandInName", "loginTrick", "script", "apk", "upiReceive", "upiNameMismatch"]

/** Hosts that hide the real destination behind a redirect. */
export const URL_SHORTENERS = [
  "bit.ly", "tinyurl.com", "t.co", "goo.gl", "is.gd", "ow.ly", "buff.ly", "rebrand.ly", "cutt.ly", "shorturl.at", "rb.gy", "t.ly", "s.id",
  "tiny.cc", "bl.ink", "short.io", "qrco.de", "qr.codes", "me-qr.com", "linktr.ee", "surl.li", "u.to", "v.gd", "lnkd.in", "shorturl.gg",
]

/** Brands quishing pages most often imitate. Pass your own via `trusted`. */
export const QR_TRUSTED_DOMAINS = [
  "paybyphone.com", "parkmobile.io", "ringgo.co.uk", "paytm.com", "phonepe.com", "google.com", "paypal.com", "amazon.in", "amazon.com",
  "flipkart.com", "irctc.co.in", "onlinesbi.sbi", "hdfcbank.com", "icicibank.com", "axisbank.com", "incometax.gov.in", "uidai.gov.in",
  "apple.com", "microsoft.com", "whatsapp.com", "instagram.com", "facebook.com", "netflix.com", "usps.com", "dhl.com", "fedex.com",
]

/**
 * Shared-hosting suffixes where anyone can register a subdomain, so "you.github.io" and
 * "scammer.github.io" are different owners (a slice of the Public Suffix List's private section).
 */
export const SHARED_HOST_SUFFIXES = [
  "github.io", "gitlab.io", "vercel.app", "netlify.app", "pages.dev", "workers.dev", "web.app", "firebaseapp.com", "herokuapp.com",
  "onrender.com", "fly.dev", "glitch.me", "replit.app", "repl.co", "ngrok.io", "ngrok-free.app", "trycloudflare.com", "azurewebsites.net",
  "blogspot.com", "wixsite.com", "weebly.com", "webflow.io", "framer.website", "carrd.co", "square.site", "myshopify.com", "s3.amazonaws.com",
  "cloudfront.net", "appspot.com", "translate.goog", "000webhostapp.com", "duckdns.org", "surge.sh",
]

const MULTI_PART = new Set(["co.uk", "org.uk", "ac.uk", "gov.uk", "co.in", "net.in", "org.in", "gov.in", "ac.in", "com.au", "co.jp", "com.br", "co.nz", "com.sg", "com.mx", "co.za", "com.my", "ae.org"])
const CONFUSABLES: Record<string, string> = { "0": "o", "1": "l", "3": "e", "5": "s", "7": "t", "8": "b", "|": "l", i: "l" }
const RECEIVE_WORDS = /\b(refund|receive|cashback|cash back|prize|reward|lottery|winning|won|claim|kyc|bonus|credit(?:ed)?|return(?:ed)?|paise wapas|प्राप्त|रिफंड)\b/i
const SAFE_SCHEMES = /^(https?:)$/

/** "pay.secure.paybyphone.co.uk" → "paybyphone.co.uk". */
export function registrableDomain(host: string) {
  const clean = host.toLowerCase().replace(/\.$/, "")
  if (/^[\d.]+$/.test(clean) || clean.startsWith("[")) return clean
  const labels = clean.split(".")
  const shared = SHARED_HOST_SUFFIXES.find((suffix) => clean === suffix || clean.endsWith(`.${suffix}`))
  if (shared) return labels.slice(-(shared.split(".").length + 1)).join(".")
  const [second, top] = labels.slice(-2)
  // co.uk, com.au, gov.in… plus the same pattern under any two-letter country code (co.kr, com.tr).
  const ccSld = MULTI_PART.has(`${second}.${top}`) || (labels.length > 2 && top?.length === 2 && /^(co|com|net|org|gov|edu|ac|ne|or|go|gob|mil|nic|res)$/.test(second ?? ""))
  return labels.slice(ccSld ? -3 : -2).join(".")
}

const label = (domain: string) => registrableDomain(domain).split(".")[0] ?? ""
const skeleton = (s: string) => Array.from(s.toLowerCase(), (ch) => CONFUSABLES[ch] ?? ch).join("").replace(/rn/g, "m").replace(/vv/g, "w").replace(/-/g, "")
const squash = (s: string) => s.toLowerCase().replace(/[^\p{L}\p{N}]/gu, "")

/** Damerau-Levenshtein (optimal string alignment): a swapped pair counts as one edit. */
function distance(a: string, b: string) {
  const d = Array.from({ length: a.length + 1 }, (_, i) => [i, ...Array<number>(b.length).fill(0)])
  for (let j = 1; j <= b.length; j++) d[0][j] = j
  for (let i = 1; i <= a.length; i++)
    for (let j = 1; j <= b.length; j++) {
      d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1))
      if (i > 1 && j > 1 && a[i - 1] === b[j - 2] && a[i - 2] === b[j - 1]) d[i][j] = Math.min(d[i][j], d[i - 2][j - 2] + 1)
    }
  return d[a.length][b.length]
}

/** Two names one or two keystrokes apart, or identical once look-alike characters are folded. */
function nearMiss(a: string, b: string) {
  if (!a || !b || a === b) return false
  if (skeleton(a) === skeleton(b)) return true
  return Math.min(a.length, b.length) >= 5 && distance(a, b) <= (b.length >= 10 ? 2 : 1)
}

/** Is `candidate` posing as `real` (poybyphone.com vs paybyphone.com, paypa1.com, paybyphone.co)? */
export function isLookalike(candidate: string, real: string) {
  if (registrableDomain(candidate) === registrableDomain(real)) return false
  const [a, b] = [label(candidate), label(real)]
  return a === b || nearMiss(a, b)
}

/** The domain written in printed text ("Pay at PayByPhone.com, zone 4021"), if any. */
export const domainIn = (text = "") => text.match(/(?:[a-z0-9-]+\.)+[a-z]{2,}(?![a-z0-9-])/i)?.[0].toLowerCase() ?? null

/** Reads a QR payload: web links, UPI payment requests, tel/sms/mailto, Wi-Fi, or plain text. Never throws. */
export function parseQr(raw: unknown): QrPayload {
  const text = typeof raw === "string" ? raw.trim() : ""
  if (!text) return { type: "empty", raw: "" }
  // Browsers drop tabs, newlines and leading control characters from URLs, so "java\tscript:" still runs.
  const lower = text.replace(/[\t\n\r]/g, "").replace(/^[\u0000-\u0020]+/, "").toLowerCase()
  if (/^(javascript|data|vbscript|file|intent|blob):/.test(lower)) return { type: "script", raw: text }
  if (lower.startsWith("upi://")) {
    const query = new URLSearchParams(text.slice(text.indexOf("?") + 1 || text.length))
    const get = (key: string) => query.get(key)?.trim() || undefined
    const mandate = lower.startsWith("upi://mandate")
    return { type: "upi", raw: text, payee: get("pa") ?? "", name: get("pn"), amount: get("am"), note: get("tn"), currency: get("cu"), mandate: mandate || undefined, recur: mandate ? get("recur") : undefined }
  }
  if (/^tel:/i.test(text)) return { type: "tel", raw: text, value: decodeSafe(text.slice(4)) }
  if (/^(sms|smsto|mms):/i.test(text)) {
    const [, rest = ""] = text.split(/:(.*)/s)
    const [number, body] = rest.includes("?body=") ? rest.split("?body=") : rest.split(":")
    return { type: "sms", raw: text, value: decodeSafe(number ?? ""), body: body ? decodeSafe(body) : undefined }
  }
  if (/^mailto:/i.test(text)) return { type: "email", raw: text, value: decodeSafe(text.slice(7).split("?")[0]) }
  if (/^wifi:/i.test(text)) return { type: "wifi", raw: text, value: text.match(/S:((?:\\.|[^;])*)/i)?.[1]?.replace(/\\(.)/g, "$1") ?? "" }
  const candidate = /^[a-z][a-z\d+.-]*:\/\//i.test(text) ? text : /^(?:[\w-]+\.)+[a-z]{2,}(?:[/:?#]|$)/i.test(text) ? `https://${text}` : null
  if (candidate) {
    try {
      const url = new URL(candidate)
      if (SAFE_SCHEMES.test(url.protocol)) return { type: "url", raw: text, url, registrable: registrableDomain(url.hostname) }
      return { type: "script", raw: text }
    } catch {
      // Not a URL after all: fall through to text.
    }
  }
  return { type: "text", raw: text, value: text }
}

function decodeSafe(value: string) {
  try {
    return decodeURIComponent(value)
  } catch {
    return value
  }
}

/** Formats a UPI amount, or returns null when it isn't a positive number. */
export function upiAmount(amount: string | undefined, currency = "INR", locale = "en-IN") {
  // UPI amounts are plain decimals ("499.00"); "1e3" or "0x10" would show a number the app may read differently.
  if (!amount || !/^\d+(?:\.\d{1,2})?$/.test(amount.trim())) return null
  const n = Number(amount)
  if (n <= 0) return null
  try {
    return new Intl.NumberFormat(locale, { style: "currency", currency }).format(n)
  } catch {
    return `${currency} ${n}`
  }
}

/**
 * Every reason to pause before acting on a scanned code. `printed` is whatever is printed or shown
 * beside the code (a domain like "paybyphone.com" or a merchant name), and `trusted` are brands to
 * test for lookalikes. Pure, so it can run on a server.
 */
export function checkQr(payload: QrPayload, printed = "", trusted: string[] = QR_TRUSTED_DOMAINS, shorteners: string[] = URL_SHORTENERS): QrIssue[] {
  const issues: QrIssue[] = []
  if (payload.type === "script") return [{ kind: "script" }]
  if (payload.type === "url") {
    const { url, registrable: actual } = payload
    const host = url.hostname.toLowerCase()
    const printedDomain = domainIn(printed)
    const printedName = printedDomain ? "" : squash(printed)
    if (url.username) issues.push({ kind: "loginTrick", shown: decodeSafe(url.username), actual })
    if (printedDomain && registrableDomain(printedDomain) !== actual)
      issues.push({ kind: "notPrinted", printed: registrableDomain(printedDomain), actual, lookalike: isLookalike(actual, printedDomain) })
    else {
      const twin = printedName.length >= 5 && nearMiss(label(actual), printedName) ? printed.trim() : trusted.find((brand) => isLookalike(actual, brand))
      if (twin) issues.push({ kind: "lookalike", twin: twin === printed.trim() ? twin : registrableDomain(twin), actual })
      else {
        const names = [...(printedName.length >= 5 ? [printedName] : []), ...trusted.map(label)]
        const brand = names.find((name) => name.length >= 5 && label(actual) !== name && skeleton(host).includes(skeleton(name)))
        if (brand) issues.push({ kind: "brandInName", brand: trusted.find((t) => label(t) === brand) ?? printed.trim(), actual })
      }
    }
    if (/\/[^/?#]+\.apk(?:$|[?#])/i.test(url.pathname)) issues.push({ kind: "apk" })
    if (shorteners.includes(actual) || shorteners.includes(host)) issues.push({ kind: "shortener", host })
    if (host.includes("xn--")) issues.push({ kind: "punycode", host })
    if (/^\d{1,3}(\.\d{1,3}){3}$/.test(host) || host.startsWith("[")) issues.push({ kind: "rawIp" })
    if (url.protocol === "http:") issues.push({ kind: "http" })
  }
  if (payload.type === "upi") {
    if (payload.note && RECEIVE_WORDS.test(payload.note)) issues.push({ kind: "upiReceive" })
    const said = printed.trim()
    if (said && payload.name && !domainIn(said)) {
      const words = (s: string) => s.toLowerCase().split(/[^\p{L}\p{N}]+/u).filter((w) => w.length >= 3 && !["the", "and", "store", "shop", "stores", "pvt", "ltd"].includes(w))
      const theirs = words(payload.name)
      if (theirs.length && !words(said).some((w) => theirs.some((n) => n === w || (w.length >= 5 && distance(n, w) <= 1))))
        issues.push({ kind: "upiNameMismatch", printed: said, name: payload.name })
    }
    if (payload.mandate) issues.push({ kind: "upiMandate", recur: payload.recur })
    const amount = upiAmount(payload.amount, payload.currency || "INR")
    if (amount) issues.push({ kind: "upiAmount", amount, currency: payload.currency || "INR" })
  }
  if (payload.type === "sms" && payload.body) issues.push({ kind: "smsBody" })
  return issues
}
